content.content:
  1	# nginx: single entry point of the browser (ADR-0003 section 2, D4).
  2	#   - Serves the Angular production build (SPA fallback to index.html).
  3	#   - Proxies an EXACT allowlist of Strapi Content API paths, GET/HEAD only.
  4	#   - Everything else under /api is 404 (findOne, /api/auth/*, /api/upload, /api/users...).
  5	# The Strapi admin does NOT go through nginx (it is published only on 127.0.0.1:1337).
  6	
  7	upstream strapi {
  8	    server cms:1337;
  9	    keepalive 8;
 10	}
 11	
 12	server {
 13	    listen 80;
 14	    listen [::]:80;
 15	    server_name _;
 16	    server_tokens off;
 17	
 18	    root /usr/share/nginx/html;
 19	    index index.html;
 20	
 21	    client_max_body_size 16k;
 22	
 23	    gzip on;
 24	    gzip_vary on;
 25	    gzip_min_length 1024;
 26	    gzip_types application/json application/javascript text/css text/plain image/svg+xml;
 27	
 28	    # ---------- Content API allowlist (api-contracts section 1) ----------
 29	    location = /api/countries {
 30	        include /etc/nginx/snippets/strapi-api.conf;
 31	    }
 32	
 33	    location = /api/form-fields {
 34	        include /etc/nginx/snippets/strapi-api.conf;
 35	    }
 36	
 37	    location = /api/plans {
 38	        include /etc/nginx/snippets/strapi-api.conf;
 39	    }
 40	
 41	    location = /api/country-selection {
 42	        include /etc/nginx/snippets/strapi-api.conf;
 43	    }
 44	
 45	    # Anything else under /api is not exposed.
 46	    location = /api {
 47	        add_header Cache-Control "no-store" always;
 48	        include /etc/nginx/snippets/security-headers.conf;
 49	        return 404;
 50	    }
 51	
 52	    location /api/ {
 53	        add_header Cache-Control "no-store" always;
 54	        include /etc/nginx/snippets/security-headers.conf;
 55	        return 404;
 56	    }
 57	
 58	    # ---------- SPA ----------
 59	    # Bundles with a content hash from `ng build` (name-XXXXXXXX.ext): cache forever.
 60	    location ~* "^/(?:.+/)?[^/]+-[A-Z0-9]{8}\.(?:js|mjs|css|woff2?|ttf|otf|png|jpe?g|gif|svg|webp|avif|ico)$" {
 61	        try_files $uri =404;
 62	        add_header Cache-Control "public, max-age=31536000, immutable" always;
 63	        include /etc/nginx/snippets/security-headers.conf;
 64	    }
 65	
 66	    # index.html is always revalidated so a new build is picked up.
 67	    location = /index.html {
 68	        add_header Cache-Control "no-cache" always;
 69	        include /etc/nginx/snippets/security-headers.conf;
 70	    }
 71	
 72	    # Client-side routes (/co, /cl/plans, ...) fall back to index.html.
 73	    location / {
 74	        try_files $uri /index.html;
 75	        include /etc/nginx/snippets/security-headers.conf;
 76	    }
 77	}
 78	# Security headers (ADR-0003 section 2). add_header is only inherited when the current
 79	# level defines none, so this file is included in EVERY location that sets add_header.
 80	add_header X-Content-Type-Options "nosniff" always;
 81	add_header Referrer-Policy "no-referrer" always;
 82	add_header Content-Security-Policy "default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; connect-src 'self'; object-src 'none'; base-uri 'self'; frame-ancestors 'none'" always;
 83	# Read-only proxy to the Strapi Content API (ADR-0003 section 2, D4).
 84	# Included ONLY from the exact-match allowlist locations of default.conf.
 85	
 86	# GET (and therefore HEAD) only; any other method gets 403.
 87	limit_except GET {
 88	    deny all;
 89	}
 90	
 91	# Best-effort rejection of draft reads. $args is the raw query, so an encoded key
 92	# (%73tatus) bypasses it: the real guarantee is the published-only middleware in Strapi.
 93	if ($args ~* "(^|&)(status|publicationFilter)(=|%5B|\[)") {
 94	    return 400;
 95	}
 96	
 97	proxy_pass http://strapi;
 98	proxy_http_version 1.1;
 99	proxy_set_header Connection "";
100	proxy_set_header Host $host;
101	proxy_set_header X-Real-IP $remote_addr;
102	proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
103	proxy_set_header X-Forwarded-Proto $scheme;
104	
105	# Never forward credentials, even if the browser sent them.
106	proxy_set_header Authorization "";
107	proxy_set_header Cookie "";
108	
109	# GET has no body: never forward one.
110	proxy_pass_request_body off;
111	proxy_set_header Content-Length "";
112	
113	proxy_connect_timeout 5s;
114	proxy_read_timeout 15s;
115	
116	# No HTTP cache anywhere: every reload asks Strapi (Q-01.20, REQ-01.6, REQ-02.23).
117	proxy_hide_header Cache-Control;
118	proxy_hide_header Expires;
119	proxy_hide_header Set-Cookie;
120	proxy_hide_header X-Powered-By;
121	# Strapi's own security headers (strapi::security) that nginx sets itself: hide them to avoid duplicates.
122	proxy_hide_header Content-Security-Policy;
123	proxy_hide_header Referrer-Policy;
124	proxy_hide_header X-Content-Type-Options;
125	add_header Cache-Control "no-store" always;
126	include /etc/nginx/snippets/security-headers.conf;
127	# Web image: compiles frontend/ with `ng build` and serves it with nginx (ADR-0003, ADR-0007 E1).
128	# Build context: repository root (docker-compose.yml: context ".", dockerfile infra/nginx/Dockerfile).
129	# Ignore rules: infra/nginx/Dockerfile.dockerignore (host node_modules never enter the image).
130	
131	# ---------- build: Angular production build ----------
132	FROM node:24.22.3-trixie-slim AS build
133	WORKDIR /app
134	ENV NG_CLI_ANALYTICS=false
135	COPY frontend/package.json frontend/package-lock.json ./
136	RUN npm ci --no-audit --no-fund
137	COPY frontend/ ./
138	RUN npx ng build --configuration production
139	
140	# ---------- runtime: nginx ----------
141	FROM nginx:1.30-alpine AS runtime
142	COPY infra/nginx/default.conf /etc/nginx/conf.d/default.conf
143	COPY infra/nginx/snippets/ /etc/nginx/snippets/
144	# @angular/build:application writes the browser bundle to dist/<project>/browser.
145	COPY --from=build /app/dist/car-insurance-quote/browser/ /usr/share/nginx/html/
146	# No `RUN nginx -t` here: the upstream host "cms" only resolves on the compose network,
147	# so the config is validated when the container starts.
148	EXPOSE 80
149	# Whole project with a single command: `docker compose up --build` (PDF: Environment).
150	#
151	#   web  nginx :80 -> host :8080. Angular build + /api proxy GET/HEAD-only with an exact
152	#        allowlist, Authorization/Cookie stripped, Cache-Control: no-store (ADR-0003).
153	#   cms  Strapi 5.63 + SQLite. Public role: only `find` on 4 types. Seed and permissions
154	#        are applied idempotently on every start. Port published ONLY on 127.0.0.1 for
155	#        the business admin (http://127.0.0.1:1337/admin); the browser app never calls it.
156	name: car-insurance-quote
157	
158	services:
159	  cms:
160	    build:
161	      context: ./cms
162	    image: car-insurance-quote/cms:local
163	    env_file:
164	      - path: ./.env.example
165	        required: true
166	      - path: ./.env
167	        required: false
168	    environment:
169	      NODE_ENV: production
170	      HOST: 0.0.0.0
171	      PORT: "1337"
172	      STRAPI_TELEMETRY_DISABLED: "true"
173	    volumes:
174	      - cms-data:/opt/app/.tmp
175	    ports:
176	      - "127.0.0.1:1337:1337"
177	    restart: unless-stopped
178	
179	  web:
180	    build:
181	      context: .
182	      dockerfile: infra/nginx/Dockerfile
183	    image: car-insurance-quote/web:local
184	    depends_on:
185	      cms:
186	        condition: service_healthy
187	    ports:
188	      - "8080:80"
189	    restart: unless-stopped
190	
191	volumes:
192	  cms-data:
193	# Example environment for `docker compose up` (CLAUDE.md section 6).
194	#
195	# All values are FICTITIOUS and public. docker-compose.yml loads this file first so the
196	# stack starts with a single command after cloning; a local `.env` (never versioned,
197	# see .gitignore) overrides any value. Use real random secrets in `.env` for anything
198	# that is not a local demo.
199	#
200	# There is NO Strapi API token here or anywhere in the project (ADR-0003, G3-3):
201	# the browser and the e2e only read through nginx as the public role.
202	# API_TOKEN_SALT and TRANSFER_TOKEN_SALT are salts that Strapi requires at start-up
203	# to hash tokens created in the admin; they are not tokens.
204	
