220	/**
221	 * Route middleware `global::published-only` (ADR-0003 section 3, REQ-01.6, REQ-02.2).
222	 *
223	 * Strapi 5 lets any role with `find` read drafts through `?status=draft`. This middleware
224	 * runs before the core `find` controller of every public content type and:
225	 *   - replaces `status` with `published`;
226	 *   - removes `publicationFilter`;
227	 *   - removes `hasPublishedVersion`, the legacy alias that Strapi 5.63 still maps to the same
228	 *     publication filter (@strapi/core document-service/transform/query.js).
229	 *
230	 * The query is reassigned (not mutated in place) so Koa re-serialises it through the
231	 * qs-based setter installed by `strapi::query`; the controller then reads the sanitised value.
232	 */
233	import type { Core } from '@strapi/strapi';
234	
235	const PUBLISHED = 'published';
236	
237	export default (_config: unknown, _ctx: { strapi: Core.Strapi }) => {
238	  return async (ctx: { query: Record<string, unknown> }, next: () => Promise<void>) => {
239	    const {
240	      publicationFilter: _publicationFilter,
241	      hasPublishedVersion: _hasPublishedVersion,
242	      ...rest
243	    } = ctx.query ?? {};
244	    ctx.query = { ...rest, status: PUBLISHED };
245	    await next();
246	  };
247	};
248	/**
249	 * Public role permissions (content-model section 4, ADR-0003 section 1, D4 refined by G3-2).
250	 *
251	 * Applied on every bootstrap, idempotently: after it runs the public role has EXACTLY the
252	 * permissions below and nothing else; the authenticated role has none; sign-ups are disabled.
253	 * Any permission added by hand in the admin is revoked on the next start (by design).
254	 *
255	 * Only `find`, no `findOne`: no read in api-contracts needs it (the chosen plan is checked
256	 * against the list, REQ-03.14). No upload, users-permissions (auth/user/role) or i18n permissions.
257	 */
258	import type { Core } from '@strapi/strapi';
259	
260	export const PUBLIC_PERMISSIONS: ReadonlyArray<{ action: string; reason: string }> = [
261	  {
262	    action: 'api::country.country.find',
263	    reason: 'Country list, country config, price factors and terms (api-contracts C1, C3, C6, C7)',
264	  },
265	  { action: 'api::form-field.form-field.find', reason: 'Step 1 fields of the country (C4)' },
266	  { action: 'api::plan.plan.find', reason: 'Plans of the country for step 2 and summary (C5)' },
267	  { action: 'api::country-selection.country-selection.find', reason: 'Texts of the / page (C2)' },
268	];
269	
270	const ROLE = 'plugin::users-permissions.role';
271	const PERMISSION = 'plugin::users-permissions.permission';
272	
273	const log = (strapi: Core.Strapi, message: string) => strapi.log.info(`[permissions] ${message}`);
274	
275	async function findRole(strapi: Core.Strapi, type: 'public' | 'authenticated') {
276	  const role = await strapi.db.query(ROLE).findOne({ where: { type } });
277	  if (!role) {
278	    throw new Error(`[permissions] users-permissions role "${type}" not found`);
279	  }
280	  return role as { id: number };
281	}
282	
283	async function permissionsOf(strapi: Core.Strapi, roleId: number) {
284	  return (await strapi.db.query(PERMISSION).findMany({ where: { role: { id: roleId } } })) as Array<{
285	    id: number;
286	    action: string;
287	  }>;
288	}
289	
290	export async function applyPublicPermissions(strapi: Core.Strapi): Promise<void> {
291	  const allowed = new Set(PUBLIC_PERMISSIONS.map((p) => p.action));
292	
293	  // Public role: grant the allowlist, revoke everything else.
294	  const publicRole = await findRole(strapi, 'public');
295	  const current = await permissionsOf(strapi, publicRole.id);
296	  const revoked: string[] = [];
297	  const kept = new Set<string>();
298	  for (const permission of current) {
299	    if (allowed.has(permission.action) && !kept.has(permission.action)) {
300	      kept.add(permission.action);
301	    } else {
302	      await strapi.db.query(PERMISSION).delete({ where: { id: permission.id } });
303	      revoked.push(permission.action);
304	    }
305	  }
306	  const granted: string[] = [];
307	  for (const action of allowed) {
308	    if (!kept.has(action)) {
309	      await strapi.db.query(PERMISSION).create({ data: { action, role: publicRole.id } });
310	      granted.push(action);
311	    }
312	  }
313	
314	  // Authenticated role: no permissions (content-model section 4).
315	  const authenticatedRole = await findRole(strapi, 'authenticated');
316	  const authenticatedRevoked: string[] = [];
317	  for (const permission of await permissionsOf(strapi, authenticatedRole.id)) {
318	    await strapi.db.query(PERMISSION).delete({ where: { id: permission.id } });
319	    authenticatedRevoked.push(permission.action);
320	  }
321	
322	  // "Enable sign-ups" = false (ADR-0003 section 1).
323	  const store = strapi.store({ type: 'plugin', name: 'users-permissions' });
324	  const advanced = ((await store.get({ key: 'advanced' })) ?? {}) as Record<string, unknown>;
325	  if (advanced.allow_register !== false) {
326	    await store.set({ key: 'advanced', value: { ...advanced, allow_register: false } });
327	    log(strapi, 'sign-ups disabled (allow_register=false)');
328	  }
329	
330	  log(strapi, `public: granted [${granted.join(', ')}], revoked [${revoked.join(', ')}]`);
331	  log(strapi, `authenticated: revoked [${authenticatedRevoked.join(', ')}]`);
332	  const final = (await permissionsOf(strapi, publicRole.id)).map((p) => p.action).sort();
333	  log(strapi, `public role now has exactly: [${final.join(', ')}]`);
334	}
