  1	import { HttpClient, HttpErrorResponse, HttpParams } from '@angular/common/http';
  2	import { Injectable, inject } from '@angular/core';
  3	import { CmsRequestError, contractError } from './cms-error';
  4	import { CmsQuery } from './cms-queries';
  5	import { UnknownRecord, isRecord } from './strapi-dto';
  6	
  7	/** Same-origin base: nginx proxies `/api` to Strapi with a GET-only allowlist (ADR-0003). */
  8	export const CMS_BASE_URL = '/api';
  9	/** Timeout per request (ADR-0004, REQ-02.21). */
 10	export const CMS_TIMEOUT_MS = 10_000;
 11	
 12	export type CmsCollectionPath = 'countries' | 'form-fields' | 'plans';
 13	export type CmsSinglePath = 'country-selection';
 14	
 15	export interface CollectionPage {
 16	  readonly data: readonly unknown[];
 17	  readonly pageCount: number;
 18	}
 19	
 20	/**
 21	 * Global shape of a collection response: `data` must be an array (api-contracts §1). A missing
 22	 * or malformed `meta.pagination.pageCount` is read as a single page.
 23	 */
 24	export function parseCollectionEnvelope(body: unknown, path: string): CollectionPage {
 25	  if (!isRecord(body) || !Array.isArray(body['data'])) {
 26	    throw contractError(`unexpected collection shape for ${path}`);
 27	  }
 28	  const meta = body['meta'];
 29	  const pagination = isRecord(meta) ? meta['pagination'] : undefined;
 30	  const pageCount = isRecord(pagination) ? pagination['pageCount'] : undefined;
 31	  return {
 32	    data: body['data'],
 33	    pageCount:
 34	      typeof pageCount === 'number' && Number.isInteger(pageCount) && pageCount > 1 ? pageCount : 1,
 35	  };
 36	}
 37	
 38	/** Global shape of a single-type response: `data` must be an object (api-contracts §1). */
 39	export function parseSingleEnvelope(body: unknown, path: string): UnknownRecord {
 40	  const data = isRecord(body) ? body['data'] : undefined;
 41	  if (!isRecord(data)) {
 42	    throw contractError(`unexpected single type shape for ${path}`);
 43	  }
 44	  return data;
 45	}
 46	
 47	/**
 48	 * Read-only client for the public Strapi REST API (api-contracts §1, ADR-0004).
 49	 *
 50	 * - Only `GET`, relative `/api/...` URLs, no `Authorization` and no cookies (REQ-01.35, D4).
 51	 * - 10 000 ms timeout per request.
 52	 * - `findAll` walks every page in series when `pageCount > 1` (REQ-02.24).
 53	 * - Any failure becomes a `CmsRequestError`, which pages show as "error de carga".
 54	 * - Honours the `AbortSignal` of `resource()`: aborting cancels the HTTP request.
 55	 */
 56	@Injectable({ providedIn: 'root' })
 57	export class CmsClient {
 58	  private readonly http = inject(HttpClient);
 59	
 60	  /** All pages of a collection, concatenated in order (C1, C4, C5). */
 61	  async findAll(
 62	    path: CmsCollectionPath,
 63	    query: CmsQuery,
 64	    signal?: AbortSignal,
 65	  ): Promise<readonly unknown[]> {
 66	    const first = parseCollectionEnvelope(
 67	      await this.get(path, { ...query, 'pagination[page]': '1' }, signal),
 68	      path,
 69	    );
 70	    const data = [...first.data];
 71	    for (let page = 2; page <= first.pageCount; page++) {
 72	      const next = parseCollectionEnvelope(
 73	        await this.get(path, { ...query, 'pagination[page]': String(page) }, signal),
 74	        path,
 75	      );
 76	      data.push(...next.data);
 77	    }
 78	    return data;
 79	  }
 80	
 81	  /** First page only (C3, C6, C7: `pageSize=2` is used to detect duplicates). */
 82	  async findFirstPage(
 83	    path: CmsCollectionPath,
 84	    query: CmsQuery,
 85	    signal?: AbortSignal,
 86	  ): Promise<readonly unknown[]> {
 87	    return parseCollectionEnvelope(await this.get(path, query, signal), path).data;
 88	  }
 89	
 90	  /** Single type (C2). A 404 (not published) is an HTTP error. */
 91	  async findSingle(
 92	    path: CmsSinglePath,
 93	    query: CmsQuery,
 94	    signal?: AbortSignal,
 95	  ): Promise<UnknownRecord> {
 96	    return parseSingleEnvelope(await this.get(path, query, signal), path);
 97	  }
 98	
 99	  private get(path: string, query: CmsQuery, signal?: AbortSignal): Promise<unknown> {
100	    return new Promise<unknown>((resolve, reject) => {
101	      if (signal?.aborted) {
102	        reject(abortError());
103	        return;
104	      }
105	      const subscription = this.http
106	        .get<unknown>(`${CMS_BASE_URL}/${path}`, {
107	          params: new HttpParams({ fromObject: query }),
108	          timeout: CMS_TIMEOUT_MS,
109	        })
110	        .subscribe({
111	          next: (body) => resolve(body),
112	          error: (error: unknown) => reject(toCmsError(error, path)),
113	        });
114	      signal?.addEventListener(
115	        'abort',
116	        () => {
117	          subscription.unsubscribe();
118	          reject(abortError());
119	        },
120	        { once: true },
121	      );
122	    });
123	  }
124	}
125	
126	function abortError(): DOMException {
127	  return new DOMException('CMS request aborted', 'AbortError');
128	}
129	
130	function toCmsError(error: unknown, path: string): CmsRequestError {
131	  if (error instanceof HttpErrorResponse) {
132	    if (error.status === 0) {
133	      return new CmsRequestError('network', `[cms] network error or timeout on ${path}`, 0);
134	    }
135	    if (error.status >= 200 && error.status < 300) {
136	      // 2xx whose body could not be parsed as JSON.
137	      return new CmsRequestError('contract', `[cms] body is not JSON on ${path}`, error.status);
138	    }
139	    return new CmsRequestError('http', `[cms] HTTP ${error.status} on ${path}`, error.status);
140	  }
141	  return new CmsRequestError('network', `[cms] request failed on ${path}`);
142	}
143	/**
144	 * Query parameters of the read-only requests C1–C7 (api-contracts §2).
145	 *
146	 * The app never sends `status` nor `publicationFilter`: the REST API returns the published version
147	 * by default and the `published-only` middleware enforces it (REQ-01.6, ADR-0003). Values are
148	 * encoded by `HttpParams`; here they are written unencoded for readability.
149	 */
150	export type CmsQuery = Readonly<Record<string, string>>;
151	
152	/** Explicit page size; Strapi `maxLimit` is 100 (REQ-02.24). */
153	export const CMS_PAGE_SIZE = 100;
154	
155	const fields = (names: readonly string[]): Record<string, string> =>
156	  Object.fromEntries(names.map((name, i) => [`fields[${i}]`, name]));
157	
158	const populate = (names: readonly string[]): Record<string, string> =>
159	  Object.fromEntries(names.map((name, i) => [`populate[${i}]`, name]));
160	
161	/** C1 — published countries for `/` and "país no disponible". */
162	export function countriesListQuery(): CmsQuery {
163	  return {
164	    ...fields(['code', 'name']),
165	    'sort[0]': 'name:asc',
166	    'pagination[pageSize]': String(CMS_PAGE_SIZE),
167	  };
168	}
169	
170	/** C2 — texts of `/` (single type). */
171	export function countrySelectionQuery(): CmsQuery {
172	  return fields(['heading', 'intro', 'countryListLabel']);
173	}
174	
175	/** C3 — data and texts of one country. `pageSize=2` detects a duplicated code. */
176	export function countryConfigQuery(countryCode: string): CmsQuery {
177	  return {
178	    'filters[code][$eq]': countryCode,
179	    ...fields(['code', 'name', 'intlLocale', 'currency', 'minimumAge']),
180	    ...populate([
181	      'wizardTexts',
182	      'formStepTexts',
183	      'plansStepTexts',
184	      'summaryStepTexts',
185	      'confirmationTexts',
186	    ]),
187	    'pagination[pageSize]': '2',
188	  };
189	}
190	
191	/** C4 — form fields of one country (paginated by `CmsClient`). */
192	export function formFieldsQuery(countryCode: string): CmsQuery {
193	  return {
194	    'filters[country][code][$eq]': countryCode,
195	    ...fields([
196	      'key',
197	      'label',
198	      'type',
199	      'required',
200	      'helpText',
201	      'errorMessage',
202	      'order',
203	      'section',
204	      'role',
205	    ]),
206	    ...populate(['options', 'validations']),
207	    'pagination[pageSize]': String(CMS_PAGE_SIZE),
208	  };
209	}
210	
211	/** C5 — active plans of one country (paginated by `CmsClient`). */
212	export function plansQuery(countryCode: string): CmsQuery {
213	  return {
214	    'filters[country][code][$eq]': countryCode,
215	    'filters[active][$eq]': 'true',
216	    ...fields([
217	      'name',
218	      'shortDescription',
219	      'basePrice',
220	      'currency',
221	      'order',
222	      'recommended',
223	      'active',
224	    ]),
225	    ...populate(['coverages', 'benefits']),
226	    'pagination[pageSize]': String(CMS_PAGE_SIZE),
227	  };
228	}
229	
230	/** C6 — price factors of one country, without texts. */
231	export function priceFactorsQuery(countryCode: string): CmsQuery {
232	  return {
233	    'filters[code][$eq]': countryCode,
234	    ...fields(['code']),
235	    ...populate(['priceFactors']),
236	    'pagination[pageSize]': '2',
237	  };
238	}
239	
240	/** C7 — terms and conditions of one country. */
241	export function termsQuery(countryCode: string): CmsQuery {
242	  return {
243	    'filters[code][$eq]': countryCode,
244	    ...fields(['code', 'termsAndConditions']),
245	    'pagination[pageSize]': '2',
246	  };
247	}
248	/**
249	 * Request-level failure of a CMS call (api-contracts §1): network error, timeout, non-2xx, body
250	 * that is not JSON or an unexpected global shape. Pages show "error de carga" + "reintentar".
251	 *
252	 * Messages only contain technical context (path, status), never user data (US-02 §7).
253	 */
254	export type CmsErrorKind = 'network' | 'http' | 'contract';
255	
256	export class CmsRequestError extends Error {
257	  constructor(
258	    readonly kind: CmsErrorKind,
259	    message: string,
260	    readonly status: number | null = null,
261	  ) {
262	    super(message);
263	    this.name = 'CmsRequestError';
264	  }
265	}
266	
267	/** Throws a contract error: the response cannot be interpreted. */
268	export function contractError(message: string): CmsRequestError {
269	  return new CmsRequestError('contract', `[cms] ${message}`);
270	}
271	
272	/**
273	 * Element-level problems are dropped by the mappers and reported here (api-contracts §1), so the
274	 * mappers stay pure and the warnings can be asserted in tests.
275	 */
276	export function logCmsWarnings(warnings: readonly string[]): void {
277	  for (const warning of warnings) {
278	    console.warn(warning);
279	  }
280	}

