 61	  pay(outcome: PaymentOutcome, signal: AbortSignal): Promise<PaymentOutcome> {
 62	    return new Promise<PaymentOutcome>((resolve, reject) => {
 63	      if (signal.aborted) {
 64	        reject(new DOMException('Payment aborted', 'AbortError'));
 65	        return;
 66	      }
 67	      const timer = setTimeout(() => resolve(outcome), this.delayMs);
 68	      signal.addEventListener(
 69	        'abort',
 70	        () => {
 71	          clearTimeout(timer);
 72	          reject(new DOMException('Payment aborted', 'AbortError'));
 73	        },
 74	        { once: true },
 75	      );
 76	    });
 77	  }
