106	/**
107	 * Readable value of one field (REQ-03.3, REQ-03.6; Q-03.4):
108	 *
109	 * - `documentNumber` role → masked with `maskDocument` (REQ-03.7). Presentation only (REQ-03.8).
110	 * - `select` → label of the current option, never the stored value.
111	 * - `checkbox` → the yes/no texts of the country.
112	 * - `date` → `Intl.DateTimeFormat` with the locale of the country, as a calendar date in UTC so
113	 *   the day never shifts with the time zone of the device.
114	 * - `number` → `Intl.NumberFormat` with the locale of the country. A `vehicleYear` is a year, not
115	 *   a quantity, so it is shown without grouping ("2018", not "2.018").
116	 * - Empty optional value → `emptyValueLabel`.
117	 */
118	export function displayValue(
119	  field: Step1FieldResult,
120	  texts: SummaryValueTexts,
121	  intlLocale: string,
122	): string {
123	  const value = field.value;
124	  if (field.type === 'checkbox') {
125	    return value === true ? texts.yesLabel : texts.noLabel;
126	  }
127	  if (value === null || value === '' || typeof value === 'boolean') {
128	    return texts.emptyValueLabel;
129	  }
130	  switch (field.type) {
131	    case 'select':
132	      return field.displayValue ?? texts.emptyValueLabel;
133	    case 'date':
134	      return formatCalendarDate(String(value), intlLocale) ?? texts.emptyValueLabel;
135	    case 'number':
136	      return typeof value === 'number'
137	        ? new Intl.NumberFormat(
138	            intlLocale,
139	            field.role === 'vehicleYear' ? { useGrouping: false } : {},
140	          ).format(value)
141	        : texts.emptyValueLabel;
142	    case 'text':
143	      return field.role === 'documentNumber' ? maskDocument(String(value)) : String(value);
144	  }
145	}
