147	/** Calendar date `YYYY-MM-DD` in the long format of the locale (`7 de mayo de 1990`). */
148	export function formatCalendarDate(value: string, intlLocale: string): string | null {
149	  const date = parseCalendarDate(value);
150	  if (!date) {
151	    return null;
152	  }
153	  return new Intl.DateTimeFormat(intlLocale, { dateStyle: 'long', timeZone: 'UTC' }).format(
154	    new Date(Date.UTC(date.year, date.month - 1, date.day)),
155	  );
156	}
