181	const ALPHANUMERIC = /[\p{L}\p{N}]/u;
182	const MAX_VISIBLE = 4;
183	
184	/**
185	 * Partially masks a document number for presentation (REQ-03.7, same rule in CO and CL).
186	 *
187	 * Only alphanumeric characters are counted (`n`). The last `min(4, floor(n / 2))` stay visible,
188	 * the other alphanumerics become `*`, and separators (`.`, `-`, space) are kept as they are.
189	 * The stored value is never changed (REQ-03.8): this is presentation only.
190	 */
191	export function maskDocument(value: string): string {
192	  const characters = Array.from(value);
193	  const alphanumericCount = characters.filter((c) => ALPHANUMERIC.test(c)).length;
194	  const visible = Math.min(MAX_VISIBLE, Math.floor(alphanumericCount / 2));
195	  const hidden = alphanumericCount - visible;
196	
197	  let seen = 0;
198	  return characters
199	    .map((c) => {
200	      if (!ALPHANUMERIC.test(c)) {
201	        return c;
202	      }
203	      seen += 1;
204	      return seen <= hidden ? '*' : c;
205	    })
206	    .join('');
207	}
208	/**
209	 * Alphabet of the random part (REQ-03.26): `A-H`, `J-N`, `P-Z` and `2-9`, without `0`, `O`, `1`
210	 * and `I`. It has exactly 32 symbols, so `byte % 32` is unbiased.
211	 */
212	export const QUOTE_NUMBER_ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
213	export const QUOTE_NUMBER_RANDOM_LENGTH = 6;
214	
215	/** Fills the buffer with random bytes (same contract as `crypto.getRandomValues`). */
216	export type RandomFill = (target: Uint8Array<ArrayBuffer>) => void;
217	
218	/** Default random source: the browser's cryptographic generator (REQ-03.26). */
219	export const cryptoRandomFill: RandomFill = (target) => {
220	  crypto.getRandomValues(target);
221	};
222	
223	/**
224	 * Simulated quote number `<CC>-<YYYYMMDD>-<XXXXXX>` (REQ-03.26): country code in upper case, UTC
225	 * date of the payment and 6 random symbols. Clock and random source are injected, so the function
226	 * is pure for tests (AC-03.27). Uniqueness is only probabilistic (no central registry, D4).
227	 */
228	export function createQuoteNumber(countryCode: string, now: Date, fillRandom: RandomFill): string {
229	  const bytes = new Uint8Array(QUOTE_NUMBER_RANDOM_LENGTH);
230	  fillRandom(bytes);
231	  const suffix = Array.from(
232	    bytes,
233	    (byte) => QUOTE_NUMBER_ALPHABET[byte % QUOTE_NUMBER_ALPHABET.length],
234	  ).join('');
235	  const date =
236	    String(now.getUTCFullYear()).padStart(4, '0') +
237	    String(now.getUTCMonth() + 1).padStart(2, '0') +
238	    String(now.getUTCDate()).padStart(2, '0');
239	  return `${countryCode.toUpperCase()}-${date}-${suffix}`;
240	}

