142	export interface Parsed<T> {
143	  /** `null` when the stored entry is missing or must be discarded. */
144	  readonly value: T | null;
145	  /** The whole entry is unusable and must be removed. */
146	  readonly discard: boolean;
147	  readonly warnings: readonly string[];
148	}
149	
150	const isObject = (value: unknown): value is Readonly<Record<string, unknown>> =>
151	  typeof value === 'object' && value !== null && !Array.isArray(value);
152	
153	const nonEmptyString = (value: unknown): value is string =>
154	  typeof value === 'string' && value !== '';
155	
156	function parseJson(
157	  raw: string,
158	  kind: WizardStorageKind,
159	): { ok: true; json: unknown } | { ok: false; warning: string } {
160	  try {
161	    return { ok: true, json: JSON.parse(raw) };
162	  } catch {
163	    return { ok: false, warning: `[storage] ${kind} discarded: invalid JSON` };
164	  }
165	}
166	
167	/**
168	 * Defensive read of step 1 (US-01 5.4): invalid JSON or shape → the entry is discarded; a value
169	 * of an unexpected type is dropped on its own. Warnings never contain values (user data).
170	 */
171	export function parseStoredStep1(raw: string): Parsed<StoredStep1> {
172	  const parsed = parseJson(raw, 'step1');
173	  if (!parsed.ok) {
174	    return { value: null, discard: true, warnings: [parsed.warning] };
175	  }
176	  const values = isObject(parsed.json) ? parsed.json['values'] : undefined;
177	  if (!isObject(values)) {
178	    return {
179	      value: null,
180	      discard: true,
181	      warnings: ['[storage] step1 discarded: unexpected shape'],
182	    };
183	  }
184	  const kept: Record<string, StoredFieldValue> = {};
185	  const warnings: string[] = [];
186	  for (const [key, value] of Object.entries(values)) {
187	    if (
188	      value === null ||
189	      typeof value === 'string' ||
190	      typeof value === 'boolean' ||
191	      (typeof value === 'number' && Number.isFinite(value))
192	    ) {
193	      kept[key] = value;
194	    } else {
195	      warnings.push(`[storage] step1 value discarded: unexpected type (key=${key})`);
196	    }
197	  }
198	  return { value: { values: kept }, discard: false, warnings };
199	}
200	
201	export function parseStoredPlan(raw: string): Parsed<StoredPlan> {
202	  const parsed = parseJson(raw, 'plan');
203	  if (!parsed.ok) {
204	    return { value: null, discard: true, warnings: [parsed.warning] };
205	  }
206	  const id = isObject(parsed.json) ? parsed.json['planDocumentId'] : undefined;
207	  if (!nonEmptyString(id)) {
208	    return { value: null, discard: true, warnings: ['[storage] plan discarded: unexpected shape'] };
209	  }
210	  return { value: { planDocumentId: id }, discard: false, warnings: [] };
211	}
212	
213	export function parseStoredConfirmation(raw: string): Parsed<StoredConfirmation> {
214	  const parsed = parseJson(raw, 'confirmation');
215	  if (!parsed.ok) {
216	    return { value: null, discard: true, warnings: [parsed.warning] };
217	  }
218	  const json = parsed.json;
219	  if (
220	    !isObject(json) ||
221	    !nonEmptyString(json['quoteNumber']) ||
222	    !nonEmptyString(json['planName']) ||
223	    typeof json['finalPrice'] !== 'number' ||
224	    !Number.isFinite(json['finalPrice']) ||
225	    !nonEmptyString(json['currency']) ||
226	    !nonEmptyString(json['paidAt'])
227	  ) {
228	    return {
229	      value: null,
230	      discard: true,
231	      warnings: ['[storage] confirmation discarded: unexpected shape'],
232	    };
233	  }
234	  return {
235	    value: {
236	      quoteNumber: json['quoteNumber'],
237	      planName: json['planName'],
238	      finalPrice: json['finalPrice'],
239	      currency: json['currency'],
240	      paidAt: json['paidAt'],
241	    },
242	    discard: false,
243	    warnings: [],
244	  };
