 49	  }
 50	  const birthday = birthdayInYear(birth, reference.year);
 51	  const hadBirthday =
 52	    reference.month > birthday.month ||
 53	    (reference.month === birthday.month && reference.day >= birthday.day);
 54	  return reference.year - birth.year - (hadBirthday ? 0 : 1);
