111	export function isLeapYear(year: number): boolean {
112	  return (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
113	}
114	
115	export function daysInMonth(year: number, month: number): number {
116	  if (month === 2) {
117	    return isLeapYear(year) ? 29 : 28;
118	  }
119	  return month === 4 || month === 6 || month === 9 || month === 11 ? 30 : 31;
