122	/** Parses a strict `YYYY-MM-DD` string that names a real day; anything else is `null`. */
123	export function parseCalendarDate(value: string): CalendarDate | null {
124	  const match = ISO_CALENDAR_DATE.exec(value);
125	  if (!match) {
126	    return null;
127	  }
128	  const year = Number(match[1]);
129	  const month = Number(match[2]);
130	  const day = Number(match[3]);
131	  if (month < 1 || month > 12 || day < 1 || day > daysInMonth(year, month)) {
132	    return null;
133	  }
134	  return { year, month, day };
