106	 * - A missing screen text only marks that screen (or summary section) as `configError`.
107	 */
108	export function mapCountryConfig(
109	  data: readonly unknown[],
110	  requestedCode: string,
111	): CountryDataMapping {
112	  if (data.length === 0) {
113	    return { status: 'notAvailable' };
114	  }
115	  if (data.length > 1) {
116	    throw contractError(`more than one country with code ${requestedCode}`);
117	  }
118	  const dto = asDto<keyof CountryConfigDto & string>(data[0]);
119	  if (!dto) {
120	    throw contractError('country is not an object');
121	  }
122	  if (dto.code !== requestedCode) {
123	    throw contractError(`country code does not match ${requestedCode}`);
124	  }
125	  const name = trimmedString(dto.name);
126	  const intlLocale = trimmedString(dto.intlLocale);
127	  const currency = trimmedString(dto.currency);
128	  if (name === null || intlLocale === null || currency === null) {
129	    throw contractError(`missing market data for ${requestedCode}`);
130	  }
131	  if (!isSupportedByIntl(intlLocale, currency)) {
132	    throw contractError(`intlLocale or currency not accepted by Intl for ${requestedCode}`);
133	  }
134	  const minimumAge = dto.minimumAge;
135	  if (typeof minimumAge !== 'number' || !Number.isInteger(minimumAge) || minimumAge < 0) {
