137	  }
138	
139	  const wizardRaw = dto.wizardTexts;
140	  const genericErrorMessage = trimmedString(
141	    isRecord(wizardRaw) ? wizardRaw['genericErrorMessage'] : null,
142	  );
143	  if (genericErrorMessage === null) {
144	    throw contractError(`missing genericErrorMessage for ${requestedCode}`);
145	  }
146	
147	  const summaryRaw = dto.summaryStepTexts;
148	  const texts: UiTexts = {
149	    wizard: mapTextGroup(wizardRaw, WIZARD_TEXT_KEYS),
150	    formStep: mapTextGroup(dto.formStepTexts, FORM_STEP_TEXT_KEYS),
151	    plansStep: mapTextGroup(dto.plansStepTexts, PLANS_STEP_TEXT_KEYS),
152	    summaryStep: {
153	      page: mapTextGroup(summaryRaw, SUMMARY_STEP_TEXT_SECTIONS.page),
154	      data: mapTextGroup(summaryRaw, SUMMARY_STEP_TEXT_SECTIONS.data),
155	      plan: mapTextGroup(summaryRaw, SUMMARY_STEP_TEXT_SECTIONS.plan),
156	      terms: mapTextGroup(summaryRaw, SUMMARY_STEP_TEXT_SECTIONS.terms),
157	      payment: mapTextGroup(summaryRaw, SUMMARY_STEP_TEXT_SECTIONS.payment),
158	    },
159	    confirmation: mapTextGroup(dto.confirmationTexts, CONFIRMATION_TEXT_KEYS),
160	  };
