154	 *
155	 * `finalPrice = Math.round(basePrice × Π factor(role, operand))`, where each factor is the
156	 * multiplier of the first valid band (configured order) whose inclusive `[min, max]` contains the
157	 * operand value, or 1 if no band matches or the role has no value. Pure: no clock, no I/O.
158	 *
159	 * @param referenceDate local calendar date `YYYY-MM-DD` ("today", injected by the caller).
160	 */
161	export function computeFinalPrice(
162	  basePrice: number,
163	  inputs: PriceInputs,
164	  rules: readonly PriceFactorRule[],
165	  referenceDate: string,
166	): FinalPrice {
